import java.util.*;

/** Black-box API (provided by the judge; do not modify). */
class Master {
    private final Set<String> words;
    private final String secret;
    private int calls = 0;
    private boolean solved = false;

    Master(String[] words, String secret) {
        this.words = new HashSet<>(Arrays.asList(words));
        this.secret = secret;
    }

    public int matchCount(String guess) {
        if (!words.contains(guess)) {
            throw new IllegalArgumentException("\"" + guess + "\" is not in words");
        }
        calls++;
        if (calls > 10) {
            throw new IllegalStateException("matchCount called more than 10 times");
        }
        int matches = 0;
        for (int i = 0; i < Math.min(guess.length(), secret.length()); i++) {
            if (guess.charAt(i) == secret.charAt(i)) matches++;
        }
        if (matches == secret.length()) solved = true;
        return matches;
    }

    boolean isSolved() {
        return solved;
    }
}

